MATCH (e:Equipment)-[:measured_by]->(s:PlantItem)
WHERE EXISTS {
  (s)-[:send_signal_to*0..]->(:ProcessInstrumentationFunction {loop_tag: 'TI-460058'})
}
RETURN DISTINCT e.tag AS tag
ORDER BY tag

MATCH (a:PlantItem {tag: 'H-39301'}), (b:PlantItem {tag: 'E-39301'})
